package com.fasterxml.jackson.databind.ser.std;

import com.fasterxml.jackson.annotation.JsonFormat;
import com.fasterxml.jackson.core.JsonGenerator;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.jsonFormatVisitors.*;
import com.fasterxml.jackson.databind.ser.BeanProperty;
import com.fasterxml.jackson.databind.ser.ContextualSerializer;
import com.fasterxml.jackson.databind.ser.std.StdDateFormat;
import com.fasterxml.jackson.databind.util.StdDateFormat;
import java.io.*;
import java.io.IOException;
import java.lang.reflect.Type;
import java.math.*;
import java.text.DateFormat;
import java.text.SimpleDateFormat;
import java.util.*;
import java.util.Date;
import java.util.Locale;
import java.util.TimeZone;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.*;

public class DateTimeSerializerBase_createContextual_TriageGen0Test {

    private TestDateTimeSerializer serializer;
    private SerializerProvider serializers;
    private BeanProperty property;
    private SerializationConfig config;

    // Concrete implementation for testing abstract class
    private static class TestDateTimeSerializer extends DateTimeSerializerBase<Date> {
        private final Boolean useTimestamp;
        private final DateFormat customFormat;

        protected TestDateTimeSerializer(Class<Date> type, Boolean useTimestamp, DateFormat customFormat) {
            super(type, useTimestamp, customFormat);
            this.useTimestamp = useTimestamp;
            this.customFormat = customFormat;
        }

        @Override
        public JsonSerializer<?> withFormat(Boolean timestamp, DateFormat customFormat) {
            return new TestDateTimeSerializer(handledType(), timestamp, customFormat);
        }

        @Override
        public void serialize(Date value, com.fasterxml.jackson.core.JsonGenerator gen, SerializerProvider serializers) {}

        @Override
        public boolean isEmpty(SerializerProvider serializers, Date value) { return false; }

        @Override
        protected long _timestamp(Date value) { return value.getTime(); }

        @Override
        public JsonNode getSchema(Type type, Type typeHint) { return null; }

        @Override
        public void acceptJsonFormatVisitor(JsonFormatVisitorWrapper visitor, JavaType typeHint) {}

        @Override
        protected boolean _asTimestamp(Date value) { return useTimestamp != null && useTimestamp; }

        @Override
        protected void _acceptJsonFormatVisitor(JsonFormatVisitorWrapper visitor, JavaType typeHint, boolean asNumber) {}

        @Override
        protected void _serializeAsString(Date value, com.fasterxml.jackson.core.JsonGenerator g, SerializerProvider provider) {}
    }

    // Mock for findFormatOverrides which is protected in the real class
    // Since we cannot easily mock protected methods of the class under test without PowerMock, 
    // we extend the test class to override the behavior of findFormatOverrides for controlled testing.
    private static class TestableDateTimeSerializer extends TestDateTimeSerializer {
        private JsonFormat.Value mockFormat;

        protected TestableDateTimeSerializer(Class<Date> type, Boolean useTimestamp, DateFormat customFormat) {
            super(type, useTimestamp, customFormat);
        }

        @Override
        protected JsonFormat.Value findFormatOverrides(SerializerProvider serializers, BeanProperty property, JavaType handledType) {
            return mockFormat;
        }

        public void setMockFormat(JsonFormat.Value format) {
            this.mockFormat = format;
        }
    }

    @Before
    public void setUp() {
        serializer = new TestableDateTimeSerializer(Date.class, false, null);
        serializers = mock(SerializerProvider.class);
        property = mock(BeanProperty.class);
        config = mock(SerializationConfig.class);

        when(serializers.getConfig()).thenReturn(config);
        when(serializers.getLocale()).thenReturn(Locale.US);
        when(serializers.getTimeZone()).thenReturn(TimeZone.getTimeZone("UTC"));
    }

    @Test
    public void testCreateContextual_PropertyNull() throws JsonMappingException {
        JsonSerializer<?> result = serializer.createContextual(serializers, null);
        assertSame(serializer, result);
    }

    @Test
    public void testCreateContextual_FormatNull() throws JsonMappingException {
        ((TestableDateTimeSerializer) serializer).setMockFormat(null);
        JsonSerializer<?> result = serializer.createContextual(serializers, property);
        assertSame(serializer, result);
    }

    @Test
    public void testCreateContextual_NumericShape() throws JsonMappingException {
        JsonFormat.Value format = mock(JsonFormat.Value.class);
        when(format.getShape()).thenReturn(JsonFormat.Shape.NUMBER_INT);
        ((TestableDateTimeSerializer) serializer).setMockFormat(format);

        JsonSerializer<?> result = serializer.createContextual(serializers, property);
        assertTrue(result instanceof TestDateTimeSerializer);
        // In the code: return withFormat(Boolean.TRUE, null)
        // We can't easily check internal state of the returned object without reflection, 
        // but we verify it's a new instance.
        assertNotSame(serializer, result);
    }

    @Test
    public void testCreateContextual_WithPattern() throws JsonMappingException {
        JsonFormat.Value format = mock(JsonFormat.Value.class);
        when(format.getShape()).thenReturn(JsonFormat.Shape.STRING);
        when(format.hasPattern()).thenReturn(true);
        when(format.getPattern()).thenReturn("yyyy-MM-dd");
        when(format.hasLocale()).thenReturn(false);
        when(format.hasTimeZone()).thenReturn(true);
        when(format.getTimeZone()).thenReturn(TimeZone.getTimeZone("GMT"));
        ((TestableDateTimeSerializer) serializer).setMockFormat(format);

        JsonSerializer<?> result = serializer.createContextual(serializers, property);
        assertTrue(result instanceof TestDateTimeSerializer);
        // Verification of pattern/timezone logic is implicit in the return of withFormat
    }

    @Test
    public void testCreateContextual_WithPatternAndLocale() throws JsonMappingException {
        JsonFormat.Value format = mock(JsonFormat.Value.class);
        when(format.getShape()).thenReturn(JsonFormat.Shape.STRING);
        when(format.hasPattern()).thenReturn(true);
        when(format.getPattern()).thenReturn("yyyy-MM-dd");
        when(format.hasLocale()).thenReturn(true);
        when(format.getLocale()).thenReturn(Locale.FRANCE);
        when(format.hasTimeZone()).thenReturn(false);
        ((TestableDateTimeSerializer) serializer).setMockFormat(format);

        JsonSerializer<?> result = serializer.createContextual(serializers, property);
        assertNotNull(result);
    }

    @Test
    public void testCreateContextual_NoChangesRequired() throws JsonMappingException {
        JsonFormat.Value format = mock(JsonFormat.Value.class);
        when(format.getShape()).thenReturn(JsonFormat.Shape.STRING);
        when(format.hasPattern()).thenReturn(false);
        when(format.hasLocale()).thenReturn(false);
        when(format.hasTimeZone()).thenReturn(false);
        ((TestableDateTimeSerializer) serializer).setMockFormat(format);

        JsonSerializer<?> result = serializer.createContextual(serializers, property);
        assertSame(serializer, result);
    }

    @Test
    public void testCreateContextual_StdDateFormatBranch() throws JsonMappingException {
        JsonFormat.Value format = mock(JsonFormat.Value.class);
        when(format.getShape()).thenReturn(JsonFormat.Shape.STRING);
        when(format.hasPattern()).thenReturn(false);
        when(format.hasLocale()).thenReturn(true);
        when(format.getLocale()).thenReturn(Locale.GERMAN);
        when(format.hasTimeZone()).thenReturn(true);
        when(format.getTimeZone()).thenReturn(TimeZone.getTimeZone("EST"));
        ((TestableDateTimeSerializer) serializer).setMockFormat(format);

        StdDateFormat stdDateFormat = new StdDateFormat();
        when(config.getDateFormat()).thenReturn(stdDateFormat);

        JsonSerializer<?> result = serializer.createContextual(serializers, property);
        assertNotNull(result);
    }

    @Test
    public void testCreateContextual_SimpleDateFormatBranch_LocaleChange() throws JsonMappingException {
        JsonFormat.Value format = mock(JsonFormat.Value.class);
        when(format.getShape()).thenReturn(JsonFormat.Shape.STRING);
        when(format.hasPattern()).thenReturn(false);
        when(format.hasLocale()).thenReturn(true);
        when(format.getLocale()).thenReturn(Locale.JAPAN);
        when(format.hasTimeZone()).thenReturn(false);
        ((TestableDateTimeSerializer) serializer).setMockFormat(format);

        SimpleDateFormat sdf = new SimpleDateFormat();
        when(config.getDateFormat()).thenReturn(sdf);

        JsonSerializer<?> result = serializer.createContextual(serializers, property);
        assertNotNull(result);
    }

    @Test
    public void testCreateContextual_SimpleDateFormatBranch_TimeZoneChange() throws JsonMappingException {
        JsonFormat.Value format = mock(JsonFormat.Value.class);
        when(format.getShape()).thenReturn(JsonFormat.Shape.STRING);
        when(format.hasPattern()).thenReturn(false);
        when(format.hasLocale()).thenReturn(false);
        when(format.hasTimeZone()).thenReturn(true);
        TimeZone newTz = TimeZone.getTimeZone("Asia/Tokyo");
        when(format.getTimeZone()).thenReturn(newTz);
        ((TestableDateTimeSerializer) serializer).setMockFormat(format);

        SimpleDateFormat sdf = new SimpleDateFormat();
        when(config.getDateFormat()).thenReturn(sdf);

        JsonSerializer<?> result = serializer.createContextual(serializers, property);
        assertNotNull(result);
    }

    @Test
    public void testCreateContextual_SimpleDateFormatBranch_Clone() throws JsonMappingException {
        JsonFormat.Value format = mock(JsonFormat.Value.class);
        when(format.getShape()).thenReturn(JsonFormat.Shape.STRING);
        when(format.hasPattern()).thenReturn(false);
        when(format.hasLocale()).thenReturn(false);
        when(format.hasTimeZone()).thenReturn(false);
        ((TestableDateTimeSerializer) serializer).setMockFormat(format);

        SimpleDateFormat sdf = new SimpleDateFormat();
        when(config.getDateFormat()).thenReturn(sdf);

        JsonSerializer<?> result = serializer.createContextual(serializers, property);
        assertNotNull(result);
    }

    @Test(expected = JsonMappingException.class)
    public void testCreateContextual_BadDateFormat() throws JsonMappingException {
        JsonFormat.Value format = mock(JsonFormat.Value.class);
        when(format.getShape()).thenReturn(JsonFormat.Shape.STRING);
        when(format.hasPattern()).thenReturn(false);
        when(format.hasLocale()).thenReturn(true);
        when(format.getLocale()).thenReturn(Locale.US);
        ((TestableDateTimeSerializer) serializer).setMockFormat(format);

        // Not a SimpleDateFormat or StdDateFormat
        DateFormat badDf = new DateFormat() {
            @Override public long getTime() { return 0; }
            @Override public void getTime(Date date) {}
            @Override public void setTime(long time) {}
            @Override public void setTimeZone(TimeZone tz) {}
            @Override public int getTimeZone(int zone) { return 0; }
            @Override public void unsetTime(int field) {}
        };
        when(config.getDateFormat()).thenReturn(badDf);

        serializer.createContextual(serializers, property);
    }
}
